import {initializeLiveRequests,liveRequestMarkup} from './live-demo.js';
import {initializeInstall} from './install.js';
import {lessons,chapters,questions,glossary} from './content.js';
import {KEY,DAY,fresh,gradeCard,dueQuestions,nextLesson,makeSession,recordGrade,localDay,streak,validateState} from './engine.js';
const root=document.querySelector('main');
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=fresh(),saveError='',storageBroken=false,loadError=false;
try{const raw=localStorage.getItem(KEY);if(raw)state=validateState(JSON.parse(raw),lessons,questions);}catch(error){loadError=true;saveError='Saved progress could not be read. Your stored data has been preserved. Export the stored file in Settings before restoring a backup or starting fresh.';}
function save(){if(loadError)return false;try{localStorage.setItem(KEY,JSON.stringify(state));storageBroken=false;saveError='';return true;}catch(error){storageBroken=true;saveError='This browser could not save progress. Keep this tab open and export a backup from Settings.';return false;}}
const warning=()=>saveError?`<div class="error" role="alert">${e(saveError)} <a href="#settings">Open Settings</a></div>`:'';
let toastTimer;
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4000);}
const link=(hash,label,cls='button')=>`<a class="${cls}" href="#${hash}">${label}</a>`;
const meter=(value,total,label)=>`<div class="meter" role="progressbar" aria-label="${e(label)}" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${total}"><span style="width:${total?100*value/total:0}%"></span></div>`;
function date(t){return new Date(t).toLocaleDateString(undefined,{month:'short',day:'numeric'});}
function when(t){if(t<=Date.now())return 'Due now';const ms=t-Date.now();if(ms<3600000)return `in ${Math.max(1,Math.ceil(ms/60000))} min`;if(ms<DAY)return `in ${Math.ceil(ms/3600000)} hours`;return date(t);}
function intervalLabel(days){if(days<1/24)return `${Math.round(days*1440)} min`;if(days<1)return `${Math.round(days*24)} hours`;return `${Math.round(days)} ${Math.round(days)===1?'day':'days'}`;}
function title(eyebrow,heading,text=''){return `<div class="pagehead"><span class="eyebrow">${e(eyebrow)}</span><h1>${heading}</h1>${text?`<p class="muted lead">${text}</p>`:''}</div>`;}
function sources(l){return `<details class="sources"><summary>Go deeper · protocol references</summary><p class="small muted">These are technical references, not required reading. The course uses original simplified explanations. Standards evolve; reference pages list updates and errata.</p>${l.sources.map(s=>`<a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)} ↗</a>`).join('')}</details>`;}
function terms(l){return `<details class="terms"><summary>Explain the key terms (${l.terms.length})</summary><dl>${l.terms.map(t=>`<dt>${e(t)}</dt><dd>${e(glossary[t])}</dd>`).join('')}</dl></details>`;}
function network(compact=false){return `<section class="network ${compact?'compact':''}" aria-label="Illustrative learning network"><div class="row"><span class="eyebrow">OUR RECURRING NETWORK</span><span class="badge">Illustrative IPv4 path</span></div><div class="networkpath"><div><span class="node">▰</span><strong>Laptop</strong><small>192.168.1.10</small></div><span class="wire">→</span><div><span class="node">⌘</span><strong>Home router</strong><small>192.168.1.1 · NAT</small></div><span class="wire">→</span><div><span class="node">◎</span><strong>ISP / Internet</strong><small>Several routed links</small></div><span class="wire">→</span><div><span class="node">▤</span><strong>Web server</strong><small>198.51.100.20</small></div></div><p class="dnsnote">Name lookup uses a separate path to your configured DNS resolver; the resolver is not necessarily on the web-data path.</p>${compact?'':`<div class="packet-inspector"><label for="hop">Inspect a stage of this example</label><select id="hop"><option value="0">1 · Leaving the laptop</option><option value="1">2 · Leaving the home router</option><option value="2">3 · Crossing the Internet</option><option value="3">4 · Reaching the server</option></select><div id="hop-detail"></div><p class="small muted">An authored explanation, not a live trace or simulation. Documentation addresses are used for remote endpoints.</p></div>`}</section>`;}
function bindNetwork(){const select=root.querySelector('#hop');if(!select)return;const data=[['192.168.1.10','198.51.100.20','Home router’s LAN interface','The local frame goes to the router’s MAC. Its enclosed IP destination is the server. ARP is needed only if the gateway mapping is unavailable.'],['203.0.113.5','198.51.100.20','Selected ISP next hop','In this example, NAT rewrites the source IP and may rewrite a port. The router builds a new envelope for the outgoing link.'],['203.0.113.5','198.51.100.20','Next hop selected at each router','Routers remove and replace local link envelopes and decrement the forwarding limit. In this simplified path, the server IP remains the destination.'],['203.0.113.5','198.51.100.20','Server interface on its final link','The server receives the packet addressed to it. A reply targets the translated public endpoint; the home router uses its mapping to deliver it back to the laptop.']];const update=()=>{const d=data[Number(select.value)];root.querySelector('#hop-detail').innerHTML=`<dl class="packetfields"><div><dt>IP source</dt><dd>${d[0]}</dd></div><div><dt>IP destination</dt><dd>${d[1]}</dd></div><div><dt>Local recipient</dt><dd>${d[2]}</dd></div></dl><p>${d[3]}</p>`;};select.onchange=update;update();}
function today(){
 const done=Object.keys(state.completed).length,next=nextLesson(state,lessons),due=dueQuestions(state,questions),todayCount=state.activity.filter(a=>localDay(a.at)===localDay(Date.now())).length;
 const active=Object.entries(state.sessions).find(([k,s])=>s.index<s.items.length);
 const nextRoute=next?`lesson/${next.id}`:'lessons';
 root.innerHTML=warning()+`<section class="hero"><div><span class="eyebrow">YOUR DAILY LEARNING DESK</span><h1>Make sense of<br>every <span class="blue">hop.</span></h1><p class="muted lead">Learn how the Internet works. Explain it in your own words. Come back when it’s time to remember.</p><span class="pill"><span class="dot"></span> Open questions. Your judgment.</span></div><div class="plan"><span class="eyebrow">${next?'YOUR NEXT LESSON':'FOUNDATIONS COMPLETE'}</span><h2>${next?e(next.title):'Keep the connections strong.'}</h2><p>${next?e(next.summary):'Return to the ideas you have learned through spaced questions and new reasoning prompts.'}</p><div class="planstats"><div><strong>${next?String(next.index+1).padStart(2,'0'):done}</strong><span>${next?'of 24 lessons':'lessons completed'}</span></div><div><strong>${due.length}</strong><span>questions due</span></div><div><strong>${next?'~10':'5–10'}</strong><span>minutes ${next?'to learn':'to review'}</span></div></div>${link(nextRoute,next?(state.reading[next.id]||state.sessions['lesson:'+next.id]?'Continue lesson':'Start next lesson')+' <span aria-hidden="true">→</span>':'Browse the course','button primary')}</div></section>
 ${active?`<div class="resume"><div><strong>You have a session in progress.</strong><p>${active[1].mode==='review'?'Spaced review':e(lessons.find(l=>l.id===active[1].lessonId)?.title)} · ${active[1].index} of ${active[1].items.length} questions rated</p></div>${link('study/'+active[0],'Resume session →','button')}</div>`:''}
 <div class="statgrid"><div class="stat"><strong>${done}<small> / 24</small></strong><span>lessons completed</span></div><div class="stat"><strong>${Object.keys(state.cards).filter(id=>state.completed[questions.find(q=>q.id===id)?.lessonId]).length}<small> / 72</small></strong><span>questions introduced</span></div><div class="stat"><strong>${todayCount}</strong><span>answers rated today</span></div><div class="stat"><strong>${streak(state.activity)}</strong><span>day learning streak</span></div></div>
 <div class="sectiontitle"><h2>A little learning, a little recall.</h2>${link('progress','See your progress ↗','textlink')}</div><div class="twocol"><article class="tile"><span class="tileicon">↻</span><h3>${due.length?'Bring it back to mind.':'Your review queue is clear.'}</h3><p>${due.length?`${due.length} questions are ready. You’ll recall the idea before seeing its explanation.`:done?'Your completed lessons will return at the intervals you set with your ratings.':'Finish your first lesson to introduce its questions. Reviews then appear here when due.'}</p><div class="actions">${due.length?'<button class="primary" data-action="review">Review due questions →</button>':link(done?'progress':nextRoute,done?'See upcoming reviews':'Begin lesson 1 →')}</div></article><article class="tile"><span class="tileicon">✎</span><h3>Think it through, then reveal.</h3><p>Answer aloud, on paper, or in the optional text box. Compare your reasoning with a detailed explanation and key points, then rate how you did.</p><p class="small muted">Again · Hard · Good · Easy. No automatic grading.</p></article></div>
 ${network(true)}<div class="sectiontitle"><h2>Your learning path</h2>${link('lessons','All 24 lessons ↗','textlink')}</div><div class="chaptergrid">${chapters.map((c,i)=>{const n=lessons.filter(l=>l.chapter===i&&state.completed[l.id]).length;return `<a class="tile chaptertile" href="#lessons/unit-${i}"><span class="eyebrow">CHAPTER ${String(i+1).padStart(2,'0')}</span><h3>${c.title}</h3><p>${c.subtitle}</p>${meter(n,4,c.title+' completion')}<span class="small muted">${n} of 4 lessons complete</span></a>`;}).join('')}</div><p class="small muted storage-note">Progress is saved in this browser on this device. Export a backup in Settings before switching browsers or devices.</p>`;
}
function course(){root.innerHTML=warning()+title('THE LEARNING PATH','One journey. <span class="blue">24 lessons.</span>','Start with the local link, then follow the request outward. Each lesson ends with three open questions. You can read ahead whenever you’re curious.')+`<div class="course-overview">${meter(Object.keys(state.completed).length,24,'Course completion')}<span>${Object.keys(state.completed).length} of 24 complete · 6 chapters · 72 question cards</span></div>`+chapters.map((c,i)=>`<section id="unit-${i}" class="courseunit"><div class="sectiontitle"><div><span class="eyebrow">CHAPTER ${String(i+1).padStart(2,'0')}</span><h2>${c.title}</h2><p class="muted">${c.subtitle}</p></div><span class="unitnumber">${String(i+1).padStart(2,'0')}</span></div><div class="lessonlist">${lessons.filter(l=>l.chapter===i).map(l=>`<a class="lessonrow" href="#lesson/${l.id}"><span class="lessonnumber ${state.completed[l.id]?'done':''}">${state.completed[l.id]?'✓':String(l.index+1).padStart(2,'0')}</span><div><h3>${e(l.title)}</h3><p>${e(l.summary)}</p></div><span class="lessonmeta">${state.completed[l.id]?'Completed':state.sessions['lesson:'+l.id]||state.reading[l.id]?'In progress':'~10 min'} <span aria-hidden="true">→</span></span></a>`).join('')}</div></section>`).join('');}
function lesson(id){const l=lessons.find(l=>l.id===id);if(!l){notFound();return;}const key='lesson:'+id,s=state.sessions[key];
 if(s&&s.index<s.items.length){study(key);return;}
 const page=Math.min(state.reading[id]||0,l.sections.length+1),count=l.sections.length+2,section=l.sections[page];
 const content=page===0?`<aside class="context"><span class="eyebrow">THE SITUATION</span><p>${e(l.summary)}</p></aside>${sectionHTML(section)}`:section?sectionHTML(section):page===l.sections.length?`<span class="eyebrow">FOLLOW THE EXAMPLE</span><h2>Put the pieces together.</h2><pre class="trace">${e(l.trace)}</pre><ol class="steps">${l.example.map(x=>`<li>${e(x)}</li>`).join('')}</ol>`:`<span class="eyebrow">BEFORE YOU TRY IT</span><h2>A distinction to keep.</h2><aside class="callout"><p>${e(l.trap)}</p></aside><p>Next, answer three questions in your own words. You can type a draft or answer aloud. Reveal the explanation when you’re ready and rate your understanding against the key points.</p><p class="muted">You can finish a lesson even if some answers need work. Your ratings schedule those ideas to return sooner.</p>`;
 root.innerHTML=warning()+`<article class="study lesson"><a class="back" href="#lessons/unit-${l.chapter}">← ${chapters[l.chapter].title}</a><div class="row"><span class="eyebrow">LESSON ${String(l.index+1).padStart(2,'0')} / 24</span><span class="badge">${state.completed[id]?'Completed · revisit anytime':'~10 minutes · 3 open questions'}</span></div><h1>${e(l.title)}</h1><p><a class="textlink" href="#reading/${l.id}">Read the full explanation from the beginning →</a></p><div class="row small muted"><span>${page<l.sections.length?'Understanding the idea':page===l.sections.length?'Worked example':'Ready to apply'} · ${page+1} of ${count}</span><span>${state.completed[id]?'✓ Completed':'Reading'}</span></div>${meter(page+1,count,'Reading sections')}<div class="readingcard">${content}</div>${terms(l)}<div class="actions readingactions"><button data-action="read-back" ${page===0?'disabled':''}>← Previous</button>${page<count-1?'<button class="primary" data-action="read-next">Continue →</button>':'<button class="primary" data-action="quiz">Try the questions →</button>'}</div><details class="full-lesson"><summary>Read the whole lesson on one page</summary>${l.sections.map(sectionHTML).join('')}<pre class="trace">${e(l.trace)}</pre><ol class="steps">${l.example.map(x=>`<li>${e(x)}</li>`).join('')}</ol><aside class="callout">${e(l.trap)}</aside></details><details><summary>Your lesson notes</summary><label for="lesson-notes">Questions, connections or things to investigate</label><textarea id="lesson-notes" placeholder="These notes stay in your browser…">${e(state.notes[id]||'')}</textarea><p class="small muted">Saved as you type when browser storage is available.</p></details>${sources(l)}</article>`;
 root.querySelector('[data-action="read-back"]').onclick=()=>{state.reading[id]=Math.max(0,page-1);save();lesson(id);scrollTop();};
 root.querySelector('[data-action="read-next"]')?.addEventListener('click',()=>{state.reading[id]=page+1;save();lesson(id);scrollTop();});
 root.querySelector('[data-action="quiz"]')?.addEventListener('click',()=>{state.sessions[key]=makeSession('lesson',l.questions,state,id);save();location.hash='study/'+key;});
 root.querySelector('#lesson-notes').oninput=ev=>{state.notes[id]=ev.target.value;persistInline();};
}
function evidenceHTML(v){return `<aside class="evidence-card"><span class="eyebrow">${e(v.label)}</span>${v.code?`<pre class="trace">${e(v.code)}</pre>`:''}${v.caption?`<p class="small muted">${e(v.caption)}</p>`:''}${v.annotations?`<dl class="field-notes">${v.annotations.map(([field,meaning])=>`<div><dt>${e(field)}</dt><dd>${e(meaning)}</dd></div>`).join('')}</dl>`:''}</aside>`;}
function sectionHTML(s){return `<section class="reading-section"><h2>${e(s.title)}</h2>${s.evidence?.before?evidenceHTML(s.evidence):''}${s.text.split(/\n\n/).map(p=>`<p>${e(p)}</p>`).join('')}${s.evidence&&!s.evidence.before?evidenceHTML(s.evidence):''}${s.liveRequest?liveRequestMarkup():''}</section>`;}
function readLesson(id){const l=lessons.find(l=>l.id===id);if(!l){notFound();return;}root.innerHTML=warning()+`<article class="study lesson"><a class="back" href="#lesson/${l.id}">← Return to your guided lesson or questions</a><span class="eyebrow">LESSON ${l.index+1} · FULL EXPLANATION</span><h1>${e(l.title)}</h1><p class="lead muted">${e(l.summary)}</p><div class="readingcard">${l.sections.map(sectionHTML).join('')}</div>${terms(l)}<div class="actions">${link('lesson/'+l.id,'Return to guided lesson →','button primary')}</div>${sources(l)}</article>`;}

function persistInline(){const old=saveError;save();if(saveError&&old!==saveError){const banner=document.createElement('div');banner.className='error';banner.setAttribute('role','alert');banner.textContent=saveError;root.prepend(banner);}}
function beginReview(){const key='review';if(!state.sessions[key]||state.sessions[key].index>=state.sessions[key].items.length){const due=dueQuestions(state,questions).slice(0,state.settings.reviewLimit);if(!due.length){toast('No questions are due yet.');return;}state.sessions[key]=makeSession('review',due,state);save();}location.hash='study/'+key;}
function study(key){const s=state.sessions[key];if(!s){root.innerHTML=title('SESSION','No active session here.','Start a lesson or a due review from Today.')+link('today','Back to Today','button primary');return;}if(s.index>=s.items.length){finish(key);return;}
 const item=s.items[s.index],q=questions.find(q=>q.id===item.id),l=lessons.find(l=>l.id===q.lessonId);
 root.innerHTML=warning()+`<article class="study"><a class="back" href="#today">← Save your place & return to Today</a><div class="row"><span class="eyebrow">${s.mode==='review'?'SPACED REVIEW':'APPLY THE IDEA'}</span><span class="badge">${s.index+1} / ${s.items.length}</span></div>${meter(s.index,s.items.length,'Questions rated')}<p><a class="textlink" href="#reading/${l.id}">Read the teaching explanation →</a></p><div class="questioncard"><div class="row"><span class="eyebrow">${e(q.kind)}</span><span class="small muted">Lesson ${l.index+1} · ${e(l.title)}</span></div><h1 class="question">${e(q.prompts[item.variant])}</h1>${q.givens?`<aside class="scenario-givens"><span class="eyebrow">SCENARIO INPUTS · AUTHORED EXAMPLE</span><pre class="trace">${e(q.givens)}</pre></aside>`:''}<label for="draft">Your reasoning <span class="muted">(optional — answering aloud works too)</span></label><textarea id="draft" placeholder="Explain what happens and why…">${e(state.drafts[q.id]||'')}</textarea>${!s.revealed?`<div class="actions"><button class="primary" data-action="reveal">Reveal answer & explanation</button></div><p class="small muted">Try retrieving the idea before revealing. Nothing here is automatically graded.</p>`:`<section class="answer"><span class="eyebrow">A WORKED ANSWER</span><p>${e(q.answer)}</p><h3>Check your reasoning</h3><ul class="checklist">${q.checks.map(c=>`<li>${e(c)}</li>`).join('')}</ul><p class="small muted">Equivalent wording is fine. Judge whether you explained the mechanism, including the points above.</p><h3>How did you do?</h3><div class="ratings">${[['again','Again','I missed the idea'],['hard','Hard','Partial or with help'],['good','Good','Correct, with effort'],['easy','Easy','Clear and confident']].map(([grade,label,hint])=>`<button class="rating ${grade}" data-grade="${grade}"><strong>${label}</strong><span>${hint}</span><small>Review in ${intervalLabel(gradeCard(state.cards[q.id],grade).interval)}</small></button>`).join('')}</div><details><summary>Read the teaching explanation again</summary>${l.sections.map(sectionHTML).join('')}<pre class="trace">${e(l.trace)}</pre><aside class="callout">${e(l.trap)}</aside>${terms(l)}${sources(l)}</details></section>`}</div><p class="small muted">Your draft and place are saved in this browser. You can leave and resume later.</p></article>`;
 root.querySelector('#draft').oninput=ev=>{state.drafts[q.id]=ev.target.value;persistInline();};
 root.querySelector('[data-action="reveal"]')?.addEventListener('click',()=>{s.revealed=true;save();study(key);root.querySelector('.answer').scrollIntoView({block:'start',behavior:'smooth'});});
 root.querySelectorAll('[data-grade]').forEach(b=>b.onclick=()=>{b.disabled=true;recordGrade(state,s,q,b.dataset.grade);if(s.index>=s.items.length&&s.mode==='lesson'&&!state.completed[s.lessonId])state.completed[s.lessonId]=Date.now();save();study(key);scrollTop();});
}
function finish(key){const s=state.sessions[key],isLesson=s.mode==='lesson',next=nextLesson(state,lessons);const soon=s.items.map(i=>state.cards[i.id]?.due).filter(Boolean).sort((a,b)=>a-b)[0];
 root.innerHTML=warning()+`<section class="study center finish"><div class="bigcheck">✓</div><span class="eyebrow">${isLesson?'LESSON COMPLETE':'REVIEW COMPLETE'}</span><h1>${isLesson?'One more piece connected.':'You brought it back.'}</h1><p class="lead muted">${s.items.length} questions rated. ${saveError?'Export a backup to keep this session safe.':'Your progress is saved in this browser.'}</p><p>Your soonest review from this session is <strong>${when(soon)}</strong>.</p><div class="resultchips">${['again','hard','good','easy'].map(g=>`<span class="pill">${g[0].toUpperCase()+g.slice(1)} · ${s.grades.filter(x=>x===g).length}</span>`).join('')}</div><p class="muted">You can stop here for today. Understanding grows as you return.</p><div class="actions">${link('today','Done for today','button primary')}${next?link('lesson/'+next.id,'Next lesson →'):link('progress','See progress')}</div></section>`;
}
function progress(){const done=Object.keys(state.completed).length,due=dueQuestions(state,questions),introduced=questions.filter(q=>state.completed[q.lessonId]&&state.cards[q.id]),upcoming=introduced.filter(q=>state.cards[q.id].due>Date.now()).sort((a,b)=>state.cards[a.id].due-state.cards[b.id].due);
 const confident=introduced.filter(q=>state.cards[q.id].interval>=7&&['good','easy'].includes(state.cards[q.id].lastGrade)).length;
 root.innerHTML=warning()+title('YOUR PROGRESS','See the connections <span class="blue">grow.</span>','Lesson completion tracks coverage. Your own question ratings determine review timing; they are not an objective mastery score.')+`<div class="statgrid"><div class="stat"><strong>${done}<small> / 24</small></strong><span>lessons completed</span></div><div class="stat"><strong>${introduced.length}<small> / 72</small></strong><span>questions introduced</span></div><div class="stat"><strong>${due.length}</strong><span>due now</span></div><div class="stat"><strong>${confident}</strong><span>rated Good/Easy · interval ≥7 days</span></div></div><div class="sectiontitle"><h2>The last two weeks</h2><span class="small muted">${streak(state.activity)} day streak</span></div><div class="activity">${Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()-13+i);const n=state.activity.filter(a=>localDay(a.at)===localDay(d)).length;return `<div class="day ${n?'used':''}" title="${e(d.toLocaleDateString())}: ${n} questions rated"><span>${d.toLocaleDateString(undefined,{weekday:'short'}).slice(0,2)}</span><strong>${n}</strong><small>${d.getDate()}</small></div>`;}).join('')}</div><div class="sectiontitle"><h2>Coverage by chapter</h2></div><div class="tile">${chapters.map((c,i)=>{const n=lessons.filter(l=>l.chapter===i&&state.completed[l.id]).length;return `<div class="chapterbar"><a href="#lessons/unit-${i}">${c.title}</a>${meter(n,4,c.title)}<span>${n}/4</span></div>`;}).join('')}</div><div class="sectiontitle"><h2>What’s coming back</h2>${due.length?'<button data-action="review">Review due questions →</button>':''}</div><div class="tile">${introduced.length?`<ul class="reviewlist">${[...due,...upcoming].slice(0,15).map(q=>`<li><div><strong>${e(lessons.find(l=>l.id===q.lessonId).title)}</strong><span class="small muted">${e(q.kind)} · ${state.cards[q.id].seen} ${state.cards[q.id].seen===1?'rating':'ratings'}</span></div><span class="badge">${when(state.cards[q.id].due)}</span></li>`).join('')}</ul>`:'<p class="muted">Complete your first lesson to introduce three review questions.</p>'}</div>`;
}
function reference(){root.innerHTML=warning()+title('THE REFERENCE SHELF','Clear up a <span class="blue">missing piece.</span>','Look up a term, revisit an explanation, or inspect the recurring network. Exploring here does not mark lessons complete.')+`<div class="reference-tabs" role="group" aria-label="Reference view"><button data-tab="terms" class="active">Concepts & terms</button><button data-tab="lessons">Full explanations</button><button data-tab="network">Our network</button></div><div id="ref-content"></div>`;
 const show=tab=>{root.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const content=root.querySelector('#ref-content');if(tab==='network'){content.innerHTML=network();bindNetwork();return;}
 content.innerHTML=`<label class="search-label" for="search">${tab==='terms'?'Search concepts and acronyms':'Search lesson explanations'}</label><input type="search" id="search" placeholder="Try ARP, certificates, congestion…"><p class="small muted" id="result-count" role="status"></p><div id="results"></div>`;
 const update=()=>{const query=content.querySelector('#search').value.toLowerCase().trim();const matches=tab==='terms'?Object.entries(glossary).filter(([t,d])=>(t+' '+d).toLowerCase().includes(query)).sort(([a],[b])=>a.localeCompare(b)):lessons.filter(l=>(l.title+' '+l.sections.map(s=>[s.text,s.evidence?.code,...(s.evidence?.annotations||[]).flat()].join(' ')).join(' ')).toLowerCase().includes(query));content.querySelector('#result-count').textContent=`${matches.length} ${tab==='terms'?'terms':'lessons'}`;content.querySelector('#results').innerHTML=matches.length?tab==='terms'?matches.map(([t,d])=>`<details class="referencecard"><summary>${e(t)}</summary><p>${e(d)}</p><div class="related">${lessons.filter(l=>l.terms.includes(t)).map(l=>link('lesson/'+l.id,e(l.title)+' →','textlink small')).join('')}</div></details>`).join(''):matches.map(l=>`<details class="referencecard"><summary>${String(l.index+1).padStart(2,'0')} · ${e(l.title)}</summary>${l.sections.map(sectionHTML).join('')}<pre class="trace">${e(l.trace)}</pre><ol class="steps">${l.example.map(t=>`<li>${e(t)}</li>`).join('')}</ol><aside class="callout">${e(l.trap)}</aside>${terms(l)}${sources(l)}<p>${link('lesson/'+l.id,'Open guided lesson →','textlink')}</p></details>`).join(''):'<div class="tile"><p>No matches. Try a shorter term, or search full explanations.</p></div>';};content.querySelector('#search').oninput=update;update();};root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>show(b.dataset.tab));show('terms');}
function download(content,name){const url=URL.createObjectURL(new Blob([content],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function settings(){root.innerHTML=warning()+title('MAKE IT YOURS','A steady pace. <span class="blue">A saved place.</span>','Your progress lives in this browser on this device. There is no account sync; a backup carries your progress to another browser.')+`<div class="twocol settings"><section class="tile"><h2>Your review rhythm</h2><label for="review-limit">Maximum questions in a new review session</label><select id="review-limit">${[5,10,20,30].map(n=>`<option value="${n}" ${state.settings.reviewLimit===n?'selected':''}>${n} questions</option>`).join('')}</select><p class="small muted">This limits session size, not which cards become due. Existing sessions keep their question list.</p><h3>What the ratings do</h3><dl><dt>Again</dt><dd>Return in 10 minutes. Use when the central idea was missing.</dd><dt>Hard</dt><dd>Return in at least 12 hours; extend an existing interval modestly.</dd><dt>Good</dt><dd>Start at 1 day, then grow the prior interval by 2.4×.</dd><dt>Easy</dt><dd>Start at 4 days, then grow the prior interval by 3.2×.</dd></dl><p class="small muted">Intervals cap at one year. This is a simple spaced-review scheduler guided by your self-ratings.</p></section><section class="tile"><h2>Progress & backups</h2><p>Backups contain completions, ratings, due dates, question drafts, notes and your current session.</p><div class="stack"><button class="primary" id="export">Export progress backup ↓</button><label class="button" for="import-file">Restore a progress backup ↑</label><input type="file" id="import-file" accept="application/json,.json" class="visuallyhidden"></div>${loadError?'<button id="export-stored">Export unreadable stored data</button>':''}<p class="small muted">Restore replaces current progress after you review and confirm it. Keep an export first when moving between devices.</p><div class="divider"></div><h3>Start over</h3><p class="small muted">Clear this app’s progress, drafts and notes in this browser.</p><button class="danger" id="reset">Reset progress…</button></section></div><section class="tile about"><span class="eyebrow">ABOUT THE COURSE</span><h2>Understand the mechanism, then use it.</h2><p>24 worked-case lessons, 72 question cards and two phrasings per card. Every lesson starts with a specific exchange or problem, explains its fields and values, and asks you to reason from self-contained scenario inputs. Lessons are complete after all three questions have been revealed and rated.</p><p>Reviews include only completed lessons. All answers are written explanations; the app does not use AI grading. Packet examples and diagrams are authored teaching material rather than live network measurements. Protocol references are included with each lesson.</p></section><dialog id="confirm-dialog" aria-labelledby="confirm-title"><div class="dialogbody"><h2 id="confirm-title"></h2><p id="confirm-body"></p><div class="actions"><button id="cancel">Cancel</button><button class="primary" id="confirm">Confirm</button></div></div></dialog>`;
 root.querySelector('#review-limit').onchange=ev=>{state.settings.reviewLimit=Number(ev.target.value);save();toast(saveError||'Review session size saved.');};
 root.querySelector('#export').onclick=()=>download(JSON.stringify(state,null,2),'learnings_web-progress-'+localDay(Date.now())+'.json');
 root.querySelector('#export-stored')?.addEventListener('click',()=>{try{download(localStorage.getItem(KEY)||'','learnings_web-stored-data.json');}catch{toast('Browser storage is not accessible.');}});
 const dialog=root.querySelector('#confirm-dialog');let action=null;
 const confirm=(heading,message,label,fn)=>{root.querySelector('#confirm-title').textContent=heading;root.querySelector('#confirm-body').textContent=message;root.querySelector('#confirm').textContent=label;action=fn;dialog.showModal();};
 root.querySelector('#cancel').onclick=()=>dialog.close();root.querySelector('#confirm').onclick=()=>{dialog.close();action?.();};
 root.querySelector('#reset').onclick=()=>confirm('Reset all progress?',`This removes ${Object.keys(state.completed).length} completed lessons and ${state.activity.length} ratings, along with drafts and notes. Export a backup first if you want to keep them.`,'Reset progress',()=>{state=fresh();loadError=false;save();settings();toast(saveError||'Progress reset.');});
 root.querySelector('#import-file').onchange=async ev=>{const file=ev.target.files?.[0];if(!file)return;try{if(file.size>10000000)throw new Error('This file is too large for a progress backup.');const imported=validateState(JSON.parse(await file.text()),lessons,questions);confirm('Restore this backup?',`The file contains ${Object.keys(imported.completed).length} completed lessons and ${imported.activity.length} ratings. It will replace the progress in this browser.`,'Restore backup',()=>{state=imported;loadError=false;save();settings();toast(saveError||'Progress restored.');});}catch(error){toast(error instanceof SyntaxError?'This file is not valid JSON.':error.message);}ev.target.value='';};
}
function notFound(){root.innerHTML=title('PAGE NOT FOUND','This path needs another hop.')+link('today','Back to Today','button primary');}
function scrollTop(){window.scrollTo({top:0,behavior:'instant'});}
function render(){const [page='today',...rest]=(location.hash.slice(1)||'today').split('/');const id=decodeURIComponent(rest.join('/'));document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+(page==='lesson'||page==='study'||page==='reading'?'lessons':page);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(page==='today')today();else if(page==='lessons')course();else if(page==='lesson')lesson(id);else if(page==='reading')readLesson(id);else if(page==='study')study(id);else if(page==='progress')progress();else if(page==='reference')reference();else if(page==='settings')settings();else notFound();
 root.querySelectorAll('[data-action="review"]').forEach(b=>b.onclick=beginReview);bindNetwork();scrollTop();if(page==='lessons'&&id)requestAnimationFrame(()=>document.getElementById(id)?.scrollIntoView({block:'start'}));root.focus({preventScroll:true});}
window.addEventListener('hashchange',render);
window.addEventListener('storage',ev=>{if(ev.key===KEY)toast('Progress changed in another tab. Reload this tab before continuing.');});
initializeLiveRequests({root,escape:e});
initializeInstall({notify:toast,beforeReload:save});
render();
